<template>
  <div class="setting grid">
    <label :id="id">{{ label }}</label>
    <small class="mb-1">{{ description }}</small>
    <ul class="radios flex">
      <li v-for="(option, index) in options" :key="option">
        <input
          type="radio"
          :id="index"
          :name="id"
          :value="option.value"
          @change="change"
          v-model="value"
        />
        <label :for="index">{{ option.name }}</label>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: "RadioOption",
  props: ["id", "label", "name", "description", "options"],
  data() {
    return {
      value: "1000",
    };
  },
  methods: {
    change() {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuChangeSettings", this.id, this.value);
    },
  },
};
</script>

<style scoped lang="scss">
.radios {
  list-style-type: none;

  li {
    float: left;
    width: 100px;
    height: 40px;
    position: relative;
    margin: 2px;
  }

  & label,
  & input {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: all 0.4s;
    border-radius: $radius-sm;
    color: $white-text;
  }

  & input[type="radio"] {
    opacity: 0.011;
    z-index: 100;
  }

  & input[type="radio"]:hover + label {
    border-color: $blue;
  }

  & input[type="radio"]:checked + label {
    background: $blue;
    border-color: $blue;
  }

  & label {
    padding: 5px;
    border: 1.5px solid lighten($foreground, 15%);
    background-color: darken($foreground, 2%);
    cursor: pointer;
    z-index: 90;
  }

  & label:hover {
    background: $blue;
    border-color: $blue;
  }
}

.setting {
  color: $white-text;

  small {
    color: darken($white-text, 40%);
  }
}
</style>
