<template>
  <template
    v-for="(value, key, index) in crosshair.getSelectedLayers[this.index]
      .settings"
    :key="index"
  >
    <!-- Toggle Setting -->
    <div class="flex flex-col" v-if="config[key].type === 0">
      <label>{{ config[key].label }}</label>
      <Toggle v-model="crosshair.getSelectedLayers[this.index].settings[key]" />
    </div>
    <!-- Slider Setting -->
    <div v-else-if="config[key].type === 1">
      <label>{{ config[key].label }}</label>
      <vue-slider
        class="ml-1 mr-1"
        v-model="crosshair.getSelectedLayers[this.index].settings[key]"
        :min="config[key].min"
        :max="config[key].max"
        :interval="config[key].step"
      />
    </div>
    <!-- Color Picker Setting -->
    <div v-else-if="config[key].type === 2">
      <label>{{ config[key].label }}</label>
      <ColorPicker
        :tooltips="false"
        v-model="crosshair.getSelectedLayers[this.index].settings[key]"
      />
    </div>
  </template>
</template>

<script>
/* eslint-disable */
import { useCrosshairStore } from "../../../../../stores/crosshair";
import VueSlider from "vue-slider-component";
import Toggle from "@vueform/toggle";
import ColorPicker from "../../../../../components/ColorPicker.vue";

export default {
  name: "CrosshairConfig",
  components: { VueSlider, Toggle, ColorPicker },
  props: ["index"],
  data() {
    return {
      colorPickerKey: 0,
    };
  },
  setup() {
    return {
      crosshair: useCrosshairStore(),
      config: useCrosshairStore().settingConfig,
    };
  },
};
</script>

<style scoped lang="scss"></style>
