<template>
  <div class="flex flex-col gap-1 p-2 relative">
    <div
      v-if="user.stats.tokens < 300 || isLoading"
      class="-m-3 h-full w-full ErrorOverlay z-10 absolute flex flex-col items-center justify-center"
    >
      <div v-if="user.stats.tokens < 300">
        <i class="fa-duotone fa-circle-xmark text-red-400 text-6xl"></i>
        <h1 class="text-xl">You don't have enough tokens to create a clan.</h1>
        <h2 class="text-md">
          You need {{ 300 - user.stats.tokens }} more tokens.
        </h2>
        <Button class="gm-button-secondary mt-2" @click="$emit('goBack')"
          >Go back</Button
        >
      </div>
      <div v-else>
        <i class="fa-duotone fa-spinner-third fa-spin text-6xl"></i>
      </div>
    </div>
    <form @submit="submit">
      <div class="flex gap-2">
        <div class="flex flex-col w-4/5">
          <label>Name</label>
          <Input
            v-model="name"
            @focus="isFocus(true)"
            @blur="isFocus(false)"
            maxlength="24"
            :invalid="this.v$.name.$error"
          />
          <InputErrorList
            v-if="this.v$.name.$error"
            :errors="this.v$.name.$errors"
          />
        </div>
        <div class="flex flex-col flex-grow">
          <label>Tag</label>
          <Input
            maxlength="4"
            v-model="tag"
            @focus="isFocus(true)"
            @blur="isFocus(false)"
            :invalid="this.v$.tag.$error"
          />
          <InputErrorList
            v-if="this.v$.tag.$error"
            :errors="this.v$.tag.$errors"
          />
        </div>
      </div>
      <div class="flex flex-col mb-2">
        <label>Short Description</label>
        <Textarea
          v-model="description"
          @focus="isFocus(true)"
          @blur="isFocus(false)"
          :invalid="this.v$.description.$error"
        />
        <InputErrorList
          v-if="this.v$.description.$error"
          :errors="this.v$.description.$errors"
        />
      </div>
      <div class="flex justify-between">
        <Button
          type="submit"
          class="gm-button-success"
          :disabled="this.v$.$error"
          >Create</Button
        >
        <Button class="gm-button-secondary" @click="$emit('goBack')"
          >Cancel</Button
        >
      </div>
    </form>
  </div>
</template>

<script>
import Input from "../../../../components/Input.vue";
import Button from "../../../../components/Button.vue";
import Textarea from "../../../../components/Textarea.vue";
import { useUserStore } from "../../../../stores/user";
import useVuelidate from "@vuelidate/core";
import { required, minLength, helpers } from "@vuelidate/validators";
import InputErrorList from "../../../../components/InputErrorList.vue";

export default {
  name: "ClansMyClanCreator",
  components: { Input, Button, Textarea, InputErrorList },
  emits: ["goBack"],
  setup() {
    return { user: useUserStore(), v$: useVuelidate() };
  },
  data() {
    return {
      name: "",
      tag: "",
      description: "",
      customErrors: {
        nameAlreadyTaken: false,
        tagAlreadyTaken: false,
      },
      isLoading: false,
    };
  },
  methods: {
    toggleTyping(state) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
    async submit(e) {
      this.isLoading = true;
      e.preventDefault();
      const result = await this.v$.$validate();
      if (!result) return (this.isLoading = false);

      // eslint-disable-next-line no-undef
      mp.trigger("createClan", this.name, this.tag, this.description);
      this.isFocus(false);
    },
  },
  validations() {
    return {
      name: {
        required: helpers.withMessage("Name field cannot be empty", required),
        minLength: helpers.withMessage(
          "Name must be at least 3 characters long",
          minLength(3)
        ),
        nameAlreadyTaken: helpers.withMessage(
          "Name already taken",
          () => !this.customErrors.nameAlreadyTaken
        ),
      },
      tag: {
        required: helpers.withMessage("Tag field cannot be empty", required),
        minLength: helpers.withMessage(
          "Tag must be at least 3 characters long",
          minLength(3)
        ),
        tagAlreadyTaken: helpers.withMessage(
          "Tag already taken",
          () => !this.customErrors.tagAlreadyTaken
        ),
      },
      description: {
        required: helpers.withMessage(
          "Description field cannot be empty",
          required
        ),
        minLength: helpers.withMessage(
          "Description must be at least 10 characters long",
          minLength(10)
        ),
      },
    };
  },
};
</script>

<style scoped lang="scss">
.ErrorOverlay {
  background: rgba($foreground, 0.95);
  border-radius: $radius-md;
}
</style>
