<template>
  <textarea
    class="gm-textarea"
    @input="this.$emit('update:modelValue', $event.target.value)"
    :class="[{ 'gm-textarea-invalid': invalid }]"
    :value="modelValue"
  />
</template>

<script>
export default {
  name: "Textarea",
  props: ["modelValue", "invalid"],
  emits: ["update:modelValue"],
};
</script>

<style scoped lang="scss"></style>
