<template>
  <div class="pr-1 overflow-auto radiusmd" style="max-height: 480px">
    <Fieldset
      v-for="(cat, index) in categories"
      :key="index"
      :title="formatTime(cat.timeLeft * 1000)"
      class="mb-3"
    >
      <div class="grid grid-cols-3 gap-2 max-h-64 overflow-auto pr-1 radiusmd">
        <InfoBox
          v-for="ch in cat.challenges"
          :key="ch"
          :title="ch.name"
          :description="ch.description"
          :backgroundImage="ch.background"
        >
          <template v-slot:right>
            <div
              class="flex flex-col justify-center items-center text-2xl h-full"
            >
              <i
                v-if="ch.progress == ch.goal"
                class="fa-duotone fa-circle-check text-green-400"
              ></i>
              <i
                v-else
                class="fa-duotone fa-circle-radiation fa-spin text-yellow-400"
              ></i>
              {{ ch.progress }}/{{ ch.goal }}
            </div>
          </template>
        </InfoBox>
      </div>
    </Fieldset>
  </div>
</template>

<script>
import Fieldset from "../../../../components/Fieldset.vue";
import { msToDHM } from "../../../../helpers/functions";
import InfoBox from "../../../../components/InfoBox.vue";

export default {
  name: "ProfileChallengesTab",
  components: { Fieldset, InfoBox },
  data() {
    return {
      categories: [
        {
          name: "Daily",
          timeLeft: 500,
          challenges: [
            {
              name: "Kurcina",
              description: "Pusi kurac",
              progress: 5,
              goal: 10,
              background:
                "https://i.gadgets360cdn.com/large/GTA_5_1591910141267.jpg",
            },
          ],
        },
      ],
    };
  },
  methods: {
    formatTime(time) {
      if (time <= 0) return "Expired";
      return msToDHM(time);
    },
  },
  mounted() {
    setInterval(() => {
      this.categories.forEach((cat) => {
        if (cat.timeLeft > 0) cat.timeLeft--;
      });
    }, 1000);
  },
};
</script>

<style scoped lang="scss">
.radiusmd {
  border-radius: $radius-md;
}
</style>
