module.exports = {
  truncateWithEllipses: function (text, max) {
    return text.substr(0, max - 1) + (text.length > max ? "…" : "");
  },
  nFormatter: function (num, digits) {
    const lookup = [
      { value: 1, symbol: "" },
      { value: 1e3, symbol: "k" },
      { value: 1e6, symbol: "M" },
      { value: 1e9, symbol: "G" },
      { value: 1e12, symbol: "T" },
      { value: 1e15, symbol: "P" },
      { value: 1e18, symbol: "E" },
    ];
    const rx = /\.0+$|(\.[0-9]*[1-9])0+$/;
    var item = lookup
      .slice()
      .reverse()
      .find(function (item) {
        return num >= item.value;
      });
    return item
      ? (num / item.value).toFixed(digits).replace(rx, "$1") + item.symbol
      : "0";
  },
  msToDHM: function (ms) {
    let d = Math.floor(ms / (1000 * 60 * 60 * 24));
    let h = Math.floor((ms % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    let m = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));
    let s = Math.floor((ms % (1000 * 60)) / 1000);
    let string = "";
    if (d > 0) string += `${d}d `;
    if (h > 0) string += `${h}h `;
    if (m > 0) string += `${m}m `;
    string += `${s}s`;
    return string;
  },
  getClanRankName: function (tier) {
    switch (tier) {
      case 0:
        return "Leader";
      case 1:
        return "Officer";
      case 2:
        return "Member";
      default:
        return "None";
    }
  },
};
