<template>
  <div class="Profile">
    <div class="ProfileContent">
      <div
        class="ProfileAvatar"
        :style="{
          backgroundImage: avatar
            ? `url('${avatar}')`
            : `url('https://ui-avatars.com/api/?background=5B91FE&color=f1f1f1&name=${name}')`,
        }"
      />
      <div class="ProfileInfo p-5 flex flex-col">
        <div class="text-2xl font-medium leading-4">{{ name }}</div>
        <div class="text-base mb-2">Created on {{ createdAt }}</div>
        <div class="flex text-base justify-between mb-1">
          <div class="ProfileCurrentLevel leading-3">Level {{ level }}</div>
          <div class="ProfileNextLevel leading-3">Level {{ level + 1 }}</div>
        </div>
        <progress
          class="ProfileLevel"
          :value="progress"
          max="100"
          :data-text="`${progress}%`"
        ></progress>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "ProfileTopBar",
  computed: {
    progress() {
      return ((this.xp / this.nextLevelXp) * 100).toFixed(0);
    },
  },
  props: {
    avatar: {},
    name: {
      default: "RotX",
    },
    createdAt: {
      default: "Sun, 17 Jul 2022 04:49:33",
    },
    level: {
      default: 1,
    },
    xp: {
      default: 69,
    },
    nextLevelXp: {
      default: 100,
    },
  },
};
</script>

<style scoped lang="scss">
.Profile {
  width: 100%;
  height: 250px;
  min-height: 250px;
  background: $foreground;
  position: relative;
  display: flex;
  align-items: center;

  .ProfileContent {
    position: absolute;
    z-index: 1;
    height: 150px;
    display: flex;
    margin-left: 50px;
    border-radius: $radius-md;
    align-items: flex-start;

    .ProfileAvatar {
      height: 150px;
      width: 150px;
      border-radius: $radius-md 0 $radius-md $radius-md;
      background-size: cover;
      background-position: center;
    }

    .ProfileInfo {
      color: $white-text;
      background-color: rgba($foreground, 1);
      border-radius: 0 $radius-md $radius-md 0;
      min-width: 400px;

      .ProfileLevel {
        width: 100%;
        height: 20px;
        text-align: center;
        position: relative;

        &::-webkit-progress-value {
          background: $blue;
          border-radius: $radius-md;
        }
        &::-webkit-progress-bar {
          background: lighten($foreground, 5%);
          border-radius: $radius-md;
        }

        &:before {
          content: attr(data-text);
          font-size: 15px;
          font-weight: 500;
          position: absolute;
        }
      }
    }
  }

  &::after {
    content: "";
    position: absolute;
    background: url("https://www.wallpapertip.com/wmimgs/21-211135_gta-5-los-santos-background.jpg")
      no-repeat center center;
    background-size: cover;
    width: 100%;
    height: 100%;
    border-radius: $radius-md;
  }
}
</style>
