<template>
  <div class="setting grid">
    <label :id="id">{{ label }}</label>
    <small class="mb-1">{{ description }}</small>
    <v-select
      :options="options"
      v-model="value"
      style="width: 200px"
      :clearable="false"
      :searchable="false"
      @update:modelValue="change"
      :reduce="(change) => change.value"
      :placeholder="'Select an option'"
    ></v-select>
  </div>
</template>

<script>
export default {
  name: "SelectOption",
  props: ["id", "label", "name", "description", "options", "devMode"],
  data() {
    return {
      value: null,
    };
  },
  methods: {
    change() {
      if (this.devMode) return;
      // eslint-disable-next-line no-undef
      mp.trigger("MenuChangeSettings", this.id, this.value);
    },
  },
};
</script>

<style scoped lang="scss">
.setting {
  color: $white-text;

  small {
    color: darken($white-text, 40%);
  }
}
</style>
