<template>
  <table class="gm-table">
    <tr>
      <th style="width: 30%">Name</th>
      <th style="width: 10%">Level</th>
      <th style="width: 50%">Rank</th>
      <th style="width: 10%; text-align: center">Actions</th>
    </tr>
    <tr v-for="(member, index) in members" :key="index">
      <td>
        {{
          member.name === user.stats.name ? `${member.name} (You)` : member.name
        }}
      </td>
      <td>{{ member.level }}</td>
      <td>{{ getTierName(member.tier) }}</td>
      <td style="padding: 5px">
        <div class="flex gap-1 items-center justify-center text-3xl">
          <i
            v-if="
              user.clan.tier < member.tier &&
              user.clan.tier < 1 &&
              user.stats.name !== member.name
            "
            class="fa-duotone fa-pen-circle text-blue-400 hover:text-blue-500 duration-200 cursor-pointer"
            v-tooltip="'Change Rank'"
            @click="changeRank(member)"
          ></i>
          <i
            v-if="
              user.clan.tier < member.tier &&
              user.clan.tier < 2 &&
              user.stats.name !== member.name
            "
            class="fa-duotone fa-circle-xmark text-red-400 hover:text-red-500 duration-200 cursor-pointer"
            v-tooltip="'Kick'"
            @click="kickMember(member)"
          ></i>
          <i
            v-if="
              user.clan.tier >= member.tier || user.stats.name === member.name
            "
            class="fa-duotone fa-lock text-gray-400 hover:text-gray-500 duration-200 cursor-pointer"
            v-tooltip="'No actions available'"
          ></i>
        </div>
      </td>
    </tr>
  </table>
</template>

<script>
import { useUserStore } from "../../../../stores/user";
import { getClanRankName } from "../../../../helpers/functions";

export default {
  name: "ClansMyClanMembers",
  setup() {
    return { user: useUserStore() };
  },
  methods: {
    changeRank(member) {
      if (this.user.clan.tier >= member.tier) return;

      global.Modal.fire({
        title: "Change Rank",
        confirmButtonText: "Change",
        showCancelButton: true,
        input: "select",
        inputOptions: {
          2: "Member",
          1: "Officer",
        },
      }).then((results) => {
        if (!results.value) return;
        // eslint-disable-next-line
        mp.trigger("setClanRank", member.id, results.value);
      });
    },
    kickMember(member) {
      if (this.user.clan.tier >= member.tier) return;

      global.Modal.fire({
        title: `Kick ${member.name}?`,
        showCancelButton: true,
        confirmButtonText: "Kick",
        focusCancel: true,
      }).then((result) => {
        if (result.isConfirmed) {
          // eslint-disable-next-line
          mp.trigger("kickClanMember", member.id);
        }
      });
    },
    getTierName(tier) {
      return getClanRankName(tier);
    },
  },
  data() {
    return {
      members: [
        {
          id: 1,
          name: "RotX",
          level: 12,
          tier: 0,
        },
        {
          id: 2,
          name: "CodeName420",
          level: 12,
          tier: 1,
        },
        {
          id: 3,
          name: "Perica",
          level: 12,
          tier: 2,
        },
      ],
    };
  },
};
</script>

<style scoped lang="scss"></style>
