<template>
  <div class="flex gap-2">
    <Card class="w-7/12" v-if="crosshair.getSelectedProfile">
      <template #header>
        <div class="flex pr-3">
          <input
            type="text"
            class="bg-transparent w-48"
            v-model="crosshair.getSelectedProfile.label"
            maxlength="15"
            v-tooltip="'Click to edit'"
            @focus="toggleTyping(true)"
            @blur="toggleTyping(false)"
          />
          <div class="flex flex-grow items-center justify-end gap-1">
            <i
              v-if="crosshair.profiles.length < 10"
              class="fa-duotone fa-clone duration-300 hover:text-yellow-400 cursor-pointer"
              @click="crosshair.cloneProfile(crosshair.getSelectedProfile)"
              v-tooltip="'Clone Profile'"
            ></i>
            <i
              v-if="crosshair.profiles.length > 1"
              class="fa-duotone fa-trash-can duration-300 hover:text-red-400 cursor-pointer"
              @click="
                crosshair.removeProfile(crosshair.getSelectedProfile.uuid)
              "
              v-tooltip="'Delete Profile'"
            ></i>
          </div>
        </div>
      </template>
      <CrosshairLayers />
    </Card>
    <Card class="w-7/12 flex justify-center items-center text-3xl" v-else>
      Create Profile First
    </Card>
    <Card class="flex-grow">
      <div
        :style="{ backgroundImage: `url('${crosshairBG}')` }"
        class="w-full h-28 flex justify-center items-center bg-no-repeat crosshair-box"
      >
        <Crosshair h="100px" w="100px" />
      </div>
      <div class="flex mt-3 gap-3">
        <Button
          v-if="crosshair.profiles.length < 10"
          @click="crosshair.addProfile"
          :class="{
            'w-full': crosshair.profiles.length < 1,
            'mb-3': crosshair.getSelectedProfile,
          }"
          >New Profile</Button
        >
        <v-select
          v-if="crosshair.profiles.length > 0 && crosshair.getSelectedProfile"
          placeholder="Select profile"
          class="flex-grow"
          v-model="crosshair.selectedProfile"
          :options="crosshair.profiles"
          :clearable="false"
          :searchable="false"
          :reduce="(p) => p.uuid"
        ></v-select>
      </div>
      <div class="grid" v-if="crosshair.getSelectedProfile">
        <div class="flex flex-col">
          <label for="crosshairEnabled">Crosshair Enabled</label>
          <Toggle
            id="crosshairEnabled"
            v-model="crosshair.getSelectedProfile.settings.enabled"
          />
        </div>
        <div class="flex flex-col">
          <label for="crosshairAlwaysOn">Always On</label>
          <Toggle
            id="crosshairAlwaysOn"
            v-model="crosshair.getSelectedProfile.settings.alwaysOn"
          />
        </div>
        <div class="flex flex-col">
          <label for="crosshairOnSnipers">Enabled On Snipers</label>
          <Toggle
            id="crosshairOnSnipers"
            v-model="crosshair.getSelectedProfile.settings.onSnipers"
          />
        </div>
      </div>
    </Card>
  </div>
</template>

<script>
import Card from "../../../../../components/Card.vue";
import Crosshair from "../../../../../components/Crosshair/Crosshair.vue";
import CrosshairLayers from "./CrosshairLayers.vue";
import Toggle from "@vueform/toggle";
import Button from "../../../../../components/Button.vue";
import { useCrosshairStore } from "../../../../../stores/crosshair";

export default {
  name: "CrosshairTab",
  props: ["devMode"],
  components: { Card, Crosshair, CrosshairLayers, Toggle, Button },
  setup() {
    return {
      crosshair: useCrosshairStore(),
    };
  },
  data() {
    return {
      crosshairBG: require("@/assets/images/crosshair-maker-background.png"),
    };
  },
  watch: {
    "crosshair.profiles": {
      handler(newVal) {
        console.log("Saving All Profiles");
        if (this.devMode) return;
        // eslint-disable-next-line
        mp.trigger("saveCrosshairProfiles", JSON.stringify(newVal));
      },
      deep: true,
    },
    "crosshair.selectedProfile": {
      handler(newVal, oldVal) {
        if (newVal === oldVal) return;
        console.log("Saving Selected Profile");
        if (this.devMode) return;
        // eslint-disable-next-line
        mp.trigger("setSelectedProfile", newVal);
      },
    },
  },
  methods: {
    toggleTyping(state) {
      if (this.devMode) return;
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
  },
};
</script>
<style scoped lang="scss">
.crosshair-box {
  border-radius: $radius-md;
}
</style>
