<template>
  <div class="CrosshairLayer">
    <div class="header">
      <div class="items">
        <i
          class="fa-duotone fa-align-left handle cursor-pointer duration-300 hover:text-blue-400"
          v-tooltip="'Drag to reorder'"
        ></i>
        <i
          v-if="collapsed"
          class="fa-duotone fa-circle-plus cursor-pointer duration-300 hover:text-green-400"
          @click="collapse"
          v-tooltip="'Extend View'"
        ></i>
        <i
          v-else
          class="fa-duotone fa-circle-minus cursor-pointer duration-300 hover:text-green-400"
          @click="collapse"
          v-tooltip="'Reduce View'"
        ></i>
        <i
          v-if="!crosshair.getSelectedLayers[index].settings.hidden"
          @click="toggleHide"
          class="fa-duotone fa-eye cursor-pointer duration-300 hover:text-purple-400"
          v-tooltip="'Hide Layer'"
        ></i>
        <i
          v-else
          @click="toggleHide"
          class="fa-duotone fa-eye-slash cursor-pointer duration-300 hover:text-purple-400"
          v-tooltip="'Show Layer'"
        ></i>
        <i
          class="fa-duotone fa-clone cursor-pointer duration-300 hover:text-yellow-400"
          @click="crosshair.cloneLayer(crosshair.getSelectedLayers[index])"
          v-tooltip="'Clone Layer'"
        ></i>
        <div class="title">
          <input
            type="text"
            v-model="crosshair.getSelectedLayers[index].label"
            class="w-40"
            maxlength="15"
            v-tooltip="'Click to edit'"
          />
        </div>
      </div>
      <i
        class="fa-duotone fa-circle-xmark cursor-pointer duration-300 hover:text-red-400"
        @click="crosshair.removeLayer(crosshair.getSelectedLayers[index].uuid)"
        v-tooltip="'Delete Layer'"
      ></i>
    </div>
    <div class="configs" v-if="!collapsed">
      <CrosshairConfig :index="index" />
    </div>
  </div>
</template>

<script>
import CrosshairConfig from "./CrosshairConfig.vue";
import { useCrosshairStore } from "../../../../../stores/crosshair";

export default {
  components: { CrosshairConfig },
  name: "CrosshairLayer",
  props: ["index"],
  setup() {
    return { crosshair: useCrosshairStore() };
  },
  methods: {
    collapse() {
      this.collapsed = !this.collapsed;
    },
    toggleHide() {
      this.crosshair.getSelectedLayers[this.index].settings.hidden =
        !this.crosshair.getSelectedLayers[this.index].settings.hidden;
    },
  },
  data() {
    return {
      collapsed: true,
    };
  },
};
</script>

<style lang="scss" scoped>
::selection {
  color: $blue;
  background: rgba($blue, 0.3);
}

.CrosshairLayer {
  background: lighten($foreground, 5%);
  border-radius: $radius-md;
  padding: 10px;
  border: 1.5px solid lighten($foreground, 15%);
  color: $white-text;
  margin-bottom: 5px;

  .header {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .items {
      display: inline-flex;
      align-items: center;
      justify-content: flex-start;
      gap: 5px;

      .title {
        flex: 1.5;
        input {
          background: transparent;
          padding-left: 5px;
          width: 100%;

          &:focus {
            outline: 2px solid rgba($blue, 0.3);
            border-radius: 5px;
          }
        }
      }

      code {
        //OLD INDEX VIEWER
        background: lighten($background, 5%);
        font-size: 12px;
        padding: 2px 5px;
        border-radius: 5px;
        flex: 1;
      }
    }

    .close {
      height: 15px;
      width: 12px;
      display: flex;
      justify-content: center;
      align-items: center;
      &:hover {
        color: rgb(255, 158, 158);
      }
    }

    .collapse {
      &:hover {
        color: $orange;
      }
    }

    .hide {
      width: 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      &:hover {
        color: lightpink;
      }
    }

    .clone {
      &:hover {
        color: lightgreen;
      }
    }
  }
}
</style>
