<template>
  <div class="ClansList">
    <div class="ClansUtils">
      <div class="ClansLeft">
        <Input v-model="search" />
        <Button
          iconR="fa-duotone fa-filter-circle-xmark"
          @click="
            this.search = '';
            this.sort = 0;
            this.sortDir = 1;
          "
          style="margin-left: 8px"
          >Clear</Button
        >
      </div>
      <div class="ClansRight">
        <Button
          :iconL="
            this.sort === 0
              ? `fa-duotone fa-arrow-${sortDir === -1 ? 'up' : 'down'}`
              : ''
          "
          style="margin-right: 8px"
          @click="sortClick(0)"
        >
          <i class="fa-duotone fa-crown"></i>
        </Button>
        <Button
          :iconL="
            this.sort === 1
              ? `fa-duotone fa-arrow-${sortDir === -1 ? 'up' : 'down'}`
              : ''
          "
          style="margin-right: 8px"
          @click="sortClick(1)"
          ><i class="fa-duotone fa-crosshairs"></i
        ></Button>
        <Button
          :iconL="
            this.sort === 2
              ? `fa-duotone fa-arrow-${sortDir === -1 ? 'up' : 'down'}`
              : ''
          "
          style="margin-right: 5px"
          @click="sortClick(2)"
          ><i class="fa-duotone fa-skull"></i
        ></Button>
      </div>
    </div>
    <ClansCardBig
      style="margin-bottom: 5px"
      v-for="clan in filterClans"
      :key="clan"
      :clan="clan"
    />
    <div v-if="filterClans.length < 1" class="ClansNotFound">
      <i class="fa-duotone fa-face-frown"></i>
      <span>No clans found</span>
    </div>
  </div>
</template>

<script>
import ClansCardBig from "./ClansCardBig.vue";
import Input from "../../../../components/Input.vue";
import Button from "../../../../components/Button.vue";

export default {
  name: "ClansList",
  components: { ClansCardBig, Input, Button },
  data() {
    return {
      sort: 0, //0 - by wins | 1 - by kills | 2 - by deaths
      sortDir: 1, //1 - asc | -1 - desc
      search: "",
      filterClans: [],
      clans: [
        {
          name: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789",
          tag: "ABC",
          description: "Must have mic & shooters only!",
          banner:
            "https://www.igta5.com/images/official-artwork-blitz-play.jpg",
          open: true,
          players: 5,
          maxplayers: 25,
          stats: {
            kills: 1205,
            deaths: 550,
            wins: 15,
          },
        },
        {
          name: "aPerica",
          tag: "PERI",
          description:
            "Must have mic & shooters only! Yes good shooter life is forbiden must have 25 mouse pads and mouses.",
          banner:
            "https://www.igta5.com/images/official-artwork-blitz-play.jpg",
          open: false,
          players: 25,
          maxplayers: 25,
          stats: {
            kills: 232,
            deaths: 521,
            wins: 16,
          },
        },
        {
          name: "Jorgan",
          tag: "JORG",
          description:
            "Must have mic & shooters only! Yes good shooter life is forbiden must have 25 mouse pads and mouses.",
          banner:
            "https://www.igta5.com/images/official-artwork-blitz-play.jpg",
          open: false,
          players: 25,
          maxplayers: 25,
          stats: {
            kills: 5123,
            deaths: 6123,
            wins: 242,
          },
        },
        {
          name: "Hakeri",
          tag: "HACK",
          description: "asd",
          banner:
            "https://www.igta5.com/images/official-artwork-blitz-play.jpg",
          open: true,
          players: 15,
          maxplayers: 25,
          stats: {
            kills: 62302,
            deaths: 50022522,
            wins: 9232222,
          },
        },
      ],
    };
  },
  methods: {
    sortClick(sort) {
      if (this.sort === sort) {
        this.sortDir *= -1;
      } else {
        this.sort = sort;
        this.sortDir = 1;
      }
      this.sortIt();
    },
    sortIt() {
      this.filterClans.sort((a, b) => {
        switch (this.sort) {
          case 0:
            return a.stats.wins < b.stats.wins ? this.sortDir : -1; //1 : -1
          case 1:
            return a.stats.kills < b.stats.kills ? this.sortDir : -1;
          case 2:
            return a.stats.deaths < b.stats.deaths ? this.sortDir : -1;
          default:
            return a.stats.wins < b.stats.wins ? this.sortDir : -1;
        }
      });
    },
    search2() {
      if (this.search.length < 1) return (this.filterClans = this.clans);

      this.filterClans = this.clans.filter((clan) => {
        return clan.name.toLowerCase().startsWith(this.search.toLowerCase());
      });
    },
  },
  watch: {
    filterClans() {
      this.sortIt();
    },
    search() {
      this.search2();
      this.sortIt();
    },
    clans: {
      handler(newValue) {
        this.filterClans = newValue;
        this.search2();
        this.sortIt();
      },
      deep: true,
    },
  },
  mounted() {
    this.filterClans = this.clans;
  },
};
</script>

<style scoped lang="scss">
.ClansNotFound {
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 10px 10px;
  font-size: 25px;
  color: $white-text;

  i {
    font-size: 35px;
  }
}

.ClansList {
  color: $white-text;
  display: flex;
  flex-direction: column;
  padding: 10px;

  .ClansUtils {
    padding: 0px 10px;
    margin-bottom: 10px;
    display: flex;
    justify-content: space-between;

    .bx {
      font-size: 20px;
    }

    .ClansLeft {
      display: flex;
    }

    .ClansRight {
      display: flex;
    }
  }
}
</style>
