<template>
  <div
    v-if="user.clan.id === -1"
    class="flex w-full h-96 items-center justify-center"
  >
    <Card title="Clan Creator" class="w-2/4">
      <ClansMyClanCreator v-if="clanCreator" @goBack="clanCreator = false" />
      <div v-else class="flex flex-col justify-center items-center p-5">
        <i class="fa-duotone fa-shield-halved text-7xl ClanShield"></i>
        <h1 class="text-xl ml-3 mr-3 mb-1">
          You are not in any clans, join one or create your own!
        </h1>
        <div class="flex justify-center items-center gap-2">
          <Button @click="clanCreator = true">Create</Button>
          <h2 class="text-lg">or</h2>
          <Button @click="switchToClansList">Join</Button>
        </div>
      </div>
    </Card>
  </div>
  <div v-else class="h-full flex flex-col">
    <ClansMyClanTopBarVue :name="name" :createdAt="createdAt" />
    <div class="MyClanNav"></div>
    <TabsWrapper :wrap="`myClanWrap`" ref="selector">
      <Tab title="Stats" tabClass="myClanTab">
        <div class="MyClanBorders">
          <ClansMyClanStats ref="statsTab" />
        </div>
      </Tab>
      <Tab title="Members" tabClass="myClanTab">
        <div class="MyClanBorders">
          <ClansMyClanMembers ref="membersTab" />
        </div>
      </Tab>
      <Tab title="Settings" tabClass="myClanTab" noPadding="true">
        <div class="MyClanBorders">
          <ClansMyClanSettings ref="settingsTab" />
        </div>
      </Tab>
    </TabsWrapper>
  </div>
</template>

<script>
import ClansMyClanTopBarVue from "./ClansMyClanTopBar.vue";
import TabsWrapper from "../../../../components/TabsWrapper.vue";
import Tab from "../../../../components/Tab.vue";
import ClansMyClanMembers from "./ClansMyClanMembers.vue";
import ClansMyClanStats from "./ClansMyClanStats.vue";
import ClansMyClanSettings from "./ClansMyClanSettings.vue";
import { useUserStore } from "../../../../stores/user";
import Button from "../../../../components/Button.vue";
import Card from "../../../../components/Card.vue";
import ClansMyClanCreator from "./ClansMyClanCreator.vue";

export default {
  name: "ClansMyClan",
  components: {
    ClansMyClanTopBarVue,
    TabsWrapper,
    Tab,
    ClansMyClanMembers,
    ClansMyClanStats,
    ClansMyClanSettings,
    Button,
    Card,
    ClansMyClanCreator,
  },
  data() {
    return {
      name: "Balkanska Scena 2.0",
      createdAt: "2222",
      clanCreator: false,
    };
  },
  setup() {
    return {
      user: useUserStore(),
    };
  },
  methods: {
    switchToClansList() {
      global.gm.$refs.mainMenu.$refs.clansTab.$refs.selector.selectedTitle =
        "Clans";
    },
  },
};
</script>

<style scoped lang="scss">
.ClanShield {
  color: $blue;
}

.MyClanBorders {
  padding: 10px;
  height: calc(100% - 60px);
  width: 100%;
  border-radius: $radius-md;
  background-color: $background;
}

.MyClanNav {
  background: $foreground;
  height: 50px;
  min-height: 50px;
  width: 100%;
}
</style>

<style lang="scss">
.myClanTab {
  background: $foreground;
  height: 100% !important;
}

.myClanWrap {
  flex-grow: 1;
  height: 100%;
  position: relative;
  .content {
    height: 100%;
  }
  .headers {
    display: flex;
    width: 100%;
    justify-content: center;
    align-items: center;
    color: #ced6e2a6;
    font-weight: 400;

    position: absolute;
    z-index: 150;
    top: -42px !important;

    .selected {
      color: $blue !important;
      background: rgba($blue, 0.1) !important;
    }

    .header {
      transition: background 0.2s;
      margin: 0px 5px 0 5px;
      display: grid;
      justify-content: center;
      align-items: center;
      cursor: pointer;
      padding: 5px 15px !important;
      border-radius: 15px;
      font-size: 17px;
      font-weight: 500;
      background: rgba($gray, 0.05);
    }
  }
}
</style>
